    def save(self, path: str) -> str:
        """Save report to file."""
        if self._pdf_buffer is None:
            self.generate()

        output_path = Path(path)

        if output_path.suffix.lower() == '.html':
            # Basic HTML export
            html = self._to_html()
            with open(output_path, 'w') as f:
